func (c *CaRegistry) WriteReportFromSyncPayloads(
	runtime cre.Runtime,
	inputs []SyncPayload,
	remainingAccounts []*solana.AccountMeta,
	computeConfig *solana.ComputeConfig,
) cre.Promise[*solana.WriteReportReply] {
	elements := make([][]byte, len(inputs))
	for i, input := range inputs {
		encoded, err := c.Codec.EncodeSyncPayloadStruct(input)
		if err != nil {
			return cre.PromiseFromResult[*solana.WriteReportReply](nil, err)
		}
		elements[i] = encoded
	}
	return c.WriteReportFromBorshEncodedVec(runtime, elements, remainingAccounts, computeConfig)
}

// Keeps SyncPayload in the Anchor IDL so CRE can generate WriteReportFromSyncPayload.
type SyncPayloadReceived struct {
	Mint     solanago.PublicKey `json:"mint"`
	Inserted uint32             `json:"inserted"`
	Payload  SyncPayload        `json:"payload"`
}

func (obj SyncPayloadReceived) MarshalWithEncoder(encoder *binary.Encoder) (err error) {
	// Serialize `Mint`:
	err = encoder.Encode(obj.Mint)
	if err != nil {
		return errors.NewField("Mint", err)
	}
	// Serialize `Inserted`:
	err = encoder.Encode(obj.Inserted)
	if err != nil {
		return errors.NewField("Inserted", err)
	}
	// Serialize `Payload`:
	err = encoder.Encode(obj.Payload)
	if err != nil {
		return errors.NewField("Payload", err)
	}
	return nil
}

func (obj SyncPayloadReceived) Marshal() ([]byte, error) {
	buf := bytes.NewBuffer(nil)
	encoder := binary.NewBorshEncoder(buf)
	err := obj.MarshalWithEncoder(encoder)
	if err != nil {
		return nil, fmt.Errorf("error while encoding SyncPayloadReceived: %w", err)
	}
	return buf.Bytes(), nil
}

func (obj *SyncPayloadReceived) UnmarshalWithDecoder(decoder *binary.Decoder) (err error) {
	// Deserialize `Mint`:
	err = decoder.Decode(&obj.Mint)
	if err != nil {
		return errors.NewField("Mint", err)
	}
	// Deserialize `Inserted`:
	err = decoder.Decode(&obj.Inserted)
	if err != nil {
		return errors.NewField("Inserted", err)
	}
	// Deserialize `Payload`:
	err = decoder.Decode(&obj.Payload)
	if err != nil {
		return errors.NewField("Payload", err)
	}
	return nil
}

func (obj *SyncPayloadReceived) Unmarshal(buf []byte) error {
	err := obj.UnmarshalWithDecoder(binary.NewBorshDecoder(buf))
	if err != nil {
		return fmt.Errorf("error while unmarshaling SyncPayloadReceived: %w", err)
	}
	return nil
}

func UnmarshalSyncPayloadReceived(buf []byte) (*SyncPayloadReceived, error) {
	obj := new(SyncPayloadReceived)
	err := obj.Unmarshal(buf)
	if err != nil {
		return nil, err
	}
	return obj, nil
}

func (c *Codec) EncodeSyncPayloadReceivedStruct(in SyncPayloadReceived) ([]byte, error) {
	return in.Marshal()
}

// WriteReportFromSyncPayloadReceived encodes the input struct, hashes the provided accounts, // generates a signed report, and submits it via WriteReport. //  // remainingAccounts must follow the keystone-forwarder account layout: //   - Index 0: forwarderState – the forwarder program's state account. //   - Index 1: forwarderAuthority – PDA derived from seeds //     ["forwarder", forwarderState, receiverProgram] under the forwarder program ID. //   - Index 2+: receiver-specific accounts required by the target program. //  // The full slice is hashed (via CalculateAccountsHash) into the report and forwarded // as WriteCreReportRequest.RemainingAccounts. The on-chain forwarder strips indices 0 and 1 // before CPI-ing into the receiver, so they must be present and correctly ordered.
func (c *CaRegistry) WriteReportFromSyncPayloadReceived(
	runtime cre.Runtime,
	input SyncPayloadReceived,
	remainingAccounts []*solana.AccountMeta,
	computeConfig *solana.ComputeConfig,
) cre.Promise[*solana.WriteReportReply] {
	encodedInput, err := c.Codec.EncodeSyncPayloadReceivedStruct(input)
	if err != nil {
		return cre.PromiseFromResult[*solana.WriteReportReply](nil, err)
	}

	encodedAccountList := bindings.CalculateAccountsHash(remainingAccounts)

	fwdReport := bindings.ForwarderReport{
		AccountHash: encodedAccountList,
		Payload:     encodedInput,
	}
	encodedFwdReport, err := fwdReport.Marshal()
	if err != nil {
		return cre.PromiseFromResult[*solana.WriteReportReply](nil, err)
	}

	promise := runtime.GenerateReport(&sdk.ReportRequest{
		EncodedPayload: encodedFwdReport,
		EncoderName:    "solana",
		HashingAlgo:    "keccak256",
		SigningAlgo:    "ecdsa",
	})

	return cre.ThenPromise(promise, func(report *cre.Report) cre.Promise[*solana.WriteReportReply] {
		return c.client.WriteReport(runtime, &solana.WriteCreReportRequest{
			ComputeConfig:     computeConfig,
			Receiver:          ProgramID.Bytes(),
			RemainingAccounts: remainingAccounts,
			Report:            report,
		})
	})
}

func (c *CaRegistry) WriteReportFromSyncPayloadReceiveds(
	runtime cre.Runtime,
	inputs []SyncPayloadReceived,
	remainingAccounts []*solana.AccountMeta,
	computeConfig *solana.ComputeConfig,
) cre.Promise[*solana.WriteReportReply] {
	elements := make([][]byte, len(inputs))
	for i, input := range inputs {
		encoded, err := c.Codec.EncodeSyncPayloadReceivedStruct(input)
		if err != nil {
			return cre.PromiseFromResult[*solana.WriteReportReply](nil, err)
		}
		elements[i] = encoded
	}
	return c.WriteReportFromBorshEncodedVec(runtime, elements, remainingAccounts, computeConfig)
}
